// @pit: {"label": "Extract news from completed calls, gifts detail, and data-center demand/supply quotes from call"}
async ({ workspace: { read }, runtime: { completedCalls } }) => {
  const cc: any = await completedCalls("toolu_bdrk_01Q1jKBCbtcfhEdvFJMpk4yX");
  const nc = cc.calls.find((c: any) => c.call === "fd.news");
  const n = nc?.value;
  const L = async (k: string) => JSON.parse((await read(`/tmp/nvda/${k}.json`, { format: "raw" })).content);
  const [call, insider] = await Promise.all([L("call"), L("insider")]);
  const gifts = insider.data.filter((t: any) => t.transactionType === "Gift").map((t: any) => [t.transactionDate, t.insiderName, t.shares, t.ownershipForm]);
  const turns = call.data as any[];
  const speakers = turns.map((t, i) => [i, t.speakerName, t.speakerRole, t.text.length]);
  const re = /(demand|supply|capacity|constrain|sold out|visibility|backlog|Rubin|Blackwell|China|H20|hyperscal|gigawatt|\$\d+(\.\d+)? (billion|trillion)|guidance|outlook|gross margin|lead time|memory|HBM|CoWoS)/i;
  const quotes: any[] = [];
  turns.forEach((t, i) => {
    if (t.speakerRole === "Operator") return;
    const sents = t.text.split(/(?<=[.!?])\s+/);
    sents.forEach((s: string) => { if (re.test(s) && s.length > 40) quotes.push([i, t.speakerName, s.slice(0, 400)]); });
  });
  return { news: n ? { url: n.url, items: n.data.map((a: any) => [a.date, a.title, a.source, a.url]) } : nc, gifts, speakers, nq: quotes.length, quotes: quotes.slice(0, 120) };
}
